import { DefaultSession } from "next-auth";

// Extend the session and token with the user id and role propagated by auth callbacks
declare module "next-auth" {
  interface Session {
    user: {
      id: string;
      role: string;
    } & DefaultSession["user"];
  }
}

declare module "next-auth/jwt" {
  interface JWT {
    id?: string;
    role?: string;
  }
}
